package gregtech.integration.groovy.cache;

import net.minecraft.launchwrapper.Launch;
import net.minecraftforge.fml.common.FMLCommonHandler;
import net.minecraftforge.fml.common.Loader;

import groovy.lang.GroovySystem;
import org.codehaus.groovy.control.CompilerConfiguration;

import java.io.IOException;
import java.io.OutputStream;
import java.net.JarURLConnection;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.file.Path;
import java.security.DigestInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.TreeMap;

/** Runtime/compiler and ordered classpath content, captured once per engine lifetime. */
public final class GroovyCacheEnvironment {

    private GroovyCacheEnvironment() {}

    public static String capture(CompilerConfiguration configuration) throws IOException {
        var paths = new LinkedHashSet<Path>();
        String generatedTransformers = "";
        for (String entry : System.getProperty("java.class.path").split(java.io.File.pathSeparator)) {
            Path path = Path.of(entry).toAbsolutePath().normalize();
            paths.add(path);
        }
        for (var source : Launch.classLoader.getSources()) {
            if (source.toExternalForm().equals("asmgen:/")) {
                // Forge creates these transformer wrappers in memory. Hash their generated bytes as
                // well as transformer order; their generator and parent classes are in the JAR inputs.
                generatedTransformers = generatedTransformerIdentity(source, Launch.classLoader.getTransformers()
                        .stream().map(transformer -> transformer.getClass().getName()).toList());
            } else paths.add(localSource(source));
        }
        for (var mod : Loader.instance().getModList()) {
            if (mod.getSource() == null) continue;
            paths.add(localSource(mod.getSource().toURI().toURL()));
        }
        // A loose development class directory cannot be identified by a release JAR checksum.
        String development = System.getProperty("crl.dev.extrapath");
        if (development != null) {
            for (String entry : development.split(java.io.File.pathSeparator)) {
                Path path = Path.of(entry).toAbsolutePath().normalize();
                paths.add(path);
            }
        }
        String settings = String.join("\n", "gtceu-cache-v1", System.getProperty("java.runtime.version"),
                System.getProperty("java.vendor"), GroovySystem.getVersion(),
                FMLCommonHandler.instance().getSide().name(), generatedTransformers,
                configuration.getSourceEncoding(), configuration.getTargetBytecode(),
                String.valueOf(configuration.getScriptBaseClass()),
                new TreeMap<>(configuration.getOptimizationOptions()).toString(),
                configuration.getCompilationCustomizers().stream().map(customizer -> customizer.getClass().getName())
                        .toList().toString());
        return ScriptCacheIdentity.environment(List.copyOf(paths), settings);
    }

    static String generatedTransformerIdentity(URL source, List<String> transformers) throws IOException {
        StringBuilder identity = new StringBuilder();
        for (String name : transformers) {
            identity.append(name).append('\n');
            if (!name.startsWith("$wrapper.")) continue;
            try {
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                URL generated = new URL(source, name.replace('.', '/') + ".class");
                try (var bytes = new DigestInputStream(generated.openStream(), digest)) {
                    bytes.transferTo(OutputStream.nullOutputStream());
                }
                identity.append(HexFormat.of().formatHex(digest.digest())).append('\n');
            } catch (NoSuchAlgorithmException impossible) {
                throw new AssertionError(impossible);
            }
        }
        return identity.toString();
    }

    /** Resolve archive entries without opening a connection or guessing a malformed loader path. */
    static Path localSource(URL source) throws IOException {
        if (source.getProtocol().equals("jar")) {
            return localSource(((JarURLConnection) source.openConnection()).getJarFileURL());
        }
        if (!source.getProtocol().equals("file")) {
            throw new IOException("Cannot fingerprint non-file class source: " + source);
        }
        try {
            return Path.of(source.toURI()).toAbsolutePath().normalize();
        } catch (URISyntaxException | IllegalArgumentException malformed) {
            throw new IOException("Cannot fingerprint class source: " + source, malformed);
        }
    }
}
